#part_page("I", [एक अनुरोध की लागत], [
  कोई एल्गोरिदम चुनने से पहले पहचानें कि उसे किस संसाधन की रक्षा करनी है। यह अध्याय ओरिजिन के कार्य, पहेली हल करने के कार्य, सत्रों और उस मेमोरी के मॉडल बनाता है जिसे अविश्वसनीय क्लाइंट सर्वर पर बनाए रखने के लिए बाध्य कर सकता है। आगे के अध्याय इन्हीं मॉडलों से डिज़ाइन के विकल्पों का मूल्यांकन करते हैं।
])

57c9f006a37b51ce:
#objectives([
  इस अध्याय के अंत तक आप गणना कर सकेंगे कि गेट ओरिजिन का कार्य बचाता है या नहीं, और बता सकेंगे कि Proof of Work क्या स्थापित करता है। आप हैश खोज का औसत और टेल निकाल सकेंगे। आप समझा सकेंगे कि सत्र पहेली की लागत को कई अनुरोधों में कैसे बाँटते हैं, और पुस्तक में इस्तेमाल किए गए पाँच अपरिवर्तनीय नियम बता सकेंगे।
])

de29137d766efee7:
#definition([उदाहरण: गेट कब अपनी लागत की भरपाई करता है], [
  ⟦0⟧ कार्य इकाइयाँ और ⟦1⟧ चुनें। यदि आधे अनुरोध अस्वीकृत हों, तो गेट वाला सिस्टम हर आगमन पर 100 के बजाय ⟦2⟧ इकाइयाँ खर्च करता है। यदि एक हज़ार में केवल एक अनुरोध अस्वीकृत हो, तो खर्च ⟦3⟧ होता है। इस मॉडल में गेट की लागत उसकी बचत से अधिक है। ये चुनी हुई संख्याएँ समय के मापन नहीं हैं। वे दिखाती हैं कि हर प्रदर्शन दावे में वर्कलोड का उल्लेख क्यों होना चाहिए।
])

